package net.officefloor.hq.app.settings;

import jakarta.validation.Valid;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.session.SessionController;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.bind.annotation.SessionAttribute;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class SettingsController {

    /**
     * The sheet's settings as the screen shows them; the clerk limit carries two decimals, or is null for none, and
     * the floor carries two decimals, the terms are whole days, the late percent carries two decimals, and the
     * policy date is null when blank (the sheet's today), and the period numbering from is null when blank (off).
     */
    public record SettingsView(String clerkLimit, String floor, int terms, String latePct, LocalDate policyDate,
            LocalDate periodNumberingFrom) {
        static SettingsView of(Sheet sheet) {
            return new SettingsView(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.getFloor().toPlainString(), sheet.getTerms(), sheet.getLatePct().toPlainString(),
                    sheet.getPolicyDate(), sheet.getPeriodNumberingFrom());
        }
    }

    /** The clerk limit as the form submits it: 0.00 or more with up to two decimals, or null for no limit. */
    public record ClerkLimitForm(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value) {
    }

    /** The floor as the form submits it: 0.00 or more with up to two decimals. */
    public record FloorForm(@NotNull @DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal value) {
    }

    /** The terms as the form submits them: a whole number of days, 0 or more. */
    public record TermsForm(@NotNull @Min(0) @Max(99999) Integer value) {
    }

    /** The late percent as the form submits it: 0.00 or more with up to two decimals. */
    public record LatePctForm(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal value) {
    }

    /** The policy date as the form submits it: a date, or null for blank (the sheet's today). */
    public record PolicyDateForm(LocalDate value) {
    }

    /** The period numbering from as the form submits it: a date, or null for blank (off). */
    public record PeriodNumberingFromForm(LocalDate value) {
    }

    /** The terms set for one grade, in whole days. */
    public record GradeTermsView(String grade, int terms) {
        static GradeTermsView of(GradeTerms t) {
            return new GradeTermsView(t.getGrade(), t.getTerms());
        }
    }

    public record RoleView(String user, String role) {
        static RoleView of(SheetRole r) {
            return new RoleView(r.getUser(), r.getRole());
        }
    }

    public record RoleForm(@NotNull String role) {
    }

    private final SettingsService service;
    private final SheetService sheets;

    public SettingsController(SettingsService service, SheetService sheets) {
        this.service = service;
        this.sheets = sheets;
    }

    @GetMapping("/settings")
    public SettingsView settings(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return SettingsView.of(sheets.load(sheetId));
    }

    @PutMapping("/settings/clerk-limit")
    public SettingsView setClerkLimit(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody ClerkLimitForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setClerkLimit(user, sheetId, form.value()));
    }

    @PutMapping("/settings/floor")
    public SettingsView setFloor(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody FloorForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setFloor(user, sheetId, form.value()));
    }

    @PutMapping("/settings/terms")
    public SettingsView setTerms(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody TermsForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setTerms(user, sheetId, form.value()));
    }

    /** The terms set per grade, by grade; a grade not listed uses the sheet's terms. */
    @GetMapping("/settings/grade-terms")
    public List<GradeTermsView> gradeTerms(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.gradeTerms(sheetId).stream().map(GradeTermsView::of).toList();
    }

    @PutMapping("/settings/grade-terms/{grade}")
    public GradeTermsView setGradeTerms(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade, @Valid @RequestBody TermsForm form,
            @SessionAttribute(SessionController.USER) String user) {
        return GradeTermsView.of(service.setGradeTerms(user, sheetId, grade, form.value()));
    }

    @PutMapping("/settings/late-pct")
    public SettingsView setLatePct(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody LatePctForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setLatePct(user, sheetId, form.value()));
    }

    @PutMapping("/settings/policy-date")
    public SettingsView setPolicyDate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody PolicyDateForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setPolicyDate(user, sheetId, form.value()));
    }

    @PutMapping("/settings/period-numbering-from")
    public SettingsView setPeriodNumberingFrom(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @Valid @RequestBody PeriodNumberingFromForm form, @SessionAttribute(SessionController.USER) String user) {
        return SettingsView.of(service.setPeriodNumberingFrom(user, sheetId, form.value()));
    }

    /** The roles set on the sheet, by user name; a name not listed is a clerk. */
    @GetMapping("/roles")
    public List<RoleView> roles(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return service.roles(sheetId).stream().map(RoleView::of).toList();
    }

    @PutMapping("/roles/{name}")
    public RoleView setRole(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId,
            @PathVariable @NotBlank @Size(max = 100) String name,
            @Valid @RequestBody RoleForm form, @SessionAttribute(SessionController.USER) String user) {
        return RoleView.of(service.setRole(user, sheetId, name, form.role()));
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** A sheet's settings: the role each user name has, the clerk limit, the floor, the terms, the late percent and the policy date. */
@Service
public class SettingsService {

    private final SheetRoleRepository roles;
    private final GradeTermsRepository gradeTerms;
    private final SheetRepository sheetRepository;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public SettingsService(SheetRoleRepository roles, GradeTermsRepository gradeTerms, SheetRepository sheetRepository,
            SheetService sheets, RollupService rollup, Audit audit) {
        this.roles = roles;
        this.gradeTerms = gradeTerms;
        this.sheetRepository = sheetRepository;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The roles set on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserAsc(sheetId);
    }

    /** The user's role on the sheet: clerk unless set otherwise. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(SheetRole.CLERK);
    }

    /** Sets the user's role on the sheet; refused unless it is clerk or steward. */
    @Transactional
    public SheetRole setRole(String by, String sheetId, String user, String role) {
        if (!SheetRole.CLERK.equals(role) && !SheetRole.STEWARD.equals(role)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "A role is clerk or steward.");
        }
        sheets.lock(sheetId);
        SheetRole r = roles.findBySheetIdAndUser(sheetId, user).orElseGet(() -> new SheetRole(sheetId, user, role));
        r.setRole(role);
        SheetRole saved;
        try {
            saved = roles.saveAndFlush(r);
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That role was just set by someone else.");
        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role);
        return saved;
    }

    /** Sets the sheet's clerk limit; null means no limit. */
    @Transactional
    public Sheet setClerkLimit(String by, String sheetId, BigDecimal limit) {
        Sheet sheet = sheets.lock(sheetId);
        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.UNNECESSARY);
        sheet.setClerkLimit(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=clerk-limit value="
                + (scaled == null ? "" : scaled.toPlainString()));
        return saved;
    }

    /** Sets the sheet's terms: the days after a claim's date it is due by. */
    @Transactional
    public Sheet setTerms(String by, String sheetId, int terms) {
        Sheet sheet = sheets.lock(sheetId);
        sheet.setTerms(terms);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=terms value=" + terms);
        return saved;
    }

    /** The terms set per grade on the sheet, by grade; a grade not listed uses the sheet's terms. */
    @Transactional(readOnly = true)
    public List<GradeTerms> gradeTerms(String sheetId) {
        return gradeTerms.findBySheetIdOrderByGradeAsc(sheetId);
    }

    /**
     * Sets the terms for one grade: the days after its date a claim is due by when its person has the grade on its
     * date. Claims already added keep the due-by they were given.
     */
    @Transactional
    public GradeTerms setGradeTerms(String by, String sheetId, String grade, int terms) {
        sheets.lock(sheetId);
        GradeTerms t = gradeTerms.findBySheetIdAndGrade(sheetId, grade)
                .orElseGet(() -> new GradeTerms(sheetId, grade, terms));
        t.setTerms(terms);
        GradeTerms saved = gradeTerms.saveAndFlush(t);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=terms-" + grade + " value="
                + terms);
        return saved;
    }

    /** The terms in force for the grade: its own, else the sheet's. */
    @Transactional(readOnly = true)
    public int termsFor(String sheetId, String grade) {
        return gradeTerms.findBySheetIdAndGrade(sheetId, grade).map(GradeTerms::getTerms)
                .orElseGet(() -> sheets.load(sheetId).getTerms());
    }

    /**
     * Sets the sheet's late percent: the percent of an overdue claim's figure added for every full 30 days it is
     * overdue. Settled figures keep what they were; the live figures it moves are rolled up.
     */
    @Transactional
    public Sheet setLatePct(String by, String sheetId, BigDecimal latePct) {
        Sheet sheet = sheets.lock(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal scaled = latePct.setScale(2, RoundingMode.UNNECESSARY);
        sheet.setLatePct(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=late-pct value="
                + scaled.toPlainString());
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /**
     * Sets the sheet's policy date (null for blank: the sheet's today): a claim rounded by a date before it rounds
     * half up, one on or after it half to even. Settled and stated figures keep what they were; the live figures it
     * moves are rolled up.
     */
    @Transactional
    public Sheet setPolicyDate(String by, String sheetId, LocalDate policyDate) {
        Sheet sheet = sheets.lock(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=policy-date value="
                + (policyDate == null ? "" : policyDate.toString()));
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /**
     * Sets the sheet's period numbering from (null for blank: off): while it is set and the sheet's today is on or
     * after it, a claim opened is numbered within its period. Claims already numbered keep their numbers.
     */
    @Transactional
    public Sheet setPeriodNumberingFrom(String by, String sheetId, LocalDate from) {
        Sheet sheet = sheets.lock(sheetId);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=period-numbering-from value="
                + (from == null ? "" : from.toString()));
        return saved;
    }

    /**
     * Sets the sheet's floor: the least a claim's live due can be. Settled, stated and closed-period figures keep
     * what they were; the live figures it moves are rolled up.
     */
    @Transactional
    public Sheet setFloor(String by, String sheetId, BigDecimal floor) {
        Sheet sheet = sheets.lock(sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        BigDecimal scaled = floor.setScale(2, RoundingMode.UNNECESSARY);
        sheet.setFloor(scaled);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=floor value="
                + scaled.toPlainString());
        rollup.recordChanges(by, sheetId, before);
        return saved;
    }

    /**
     * Whether the user settling a claim with the due (null for n/a) needs a steward's approval: they are a clerk and
     * the due is above the sheet's clerk limit. A steward settles anything, and an n/a due is within any limit.
     */
    @Transactional(readOnly = true)
    public boolean aboveClerkLimit(String sheetId, String user, BigDecimal due) {
        BigDecimal limit = sheets.load(sheetId).getClerkLimit();
        if (limit == null || due == null || due.compareTo(limit) <= 0) {
            return false;
        }
        return !isSteward(sheetId, user);
    }

    /** Whether the user is a steward of the sheet. */
    @Transactional(readOnly = true)
    public boolean isSteward(String sheetId, String user) {
        return SheetRole.STEWARD.equals(roleOf(sheetId, user));
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import java.time.LocalDate;

/** A sheet, chosen by its id. Everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** The sheet's own today: date decisions and default dates use it, never the real clock. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The most a clerk may settle a claim for; null means no limit. */
    @Column(name = "clerk_limit")
    private BigDecimal clerkLimit;

    /** The least a claim's live due can be. */
    @Column(name = "due_floor", nullable = false, precision = 14, scale = 2)
    private BigDecimal floor = new BigDecimal("1.00");

    /** The days a claim has to be settled in: its due-by is its date plus these. */
    @Column(name = "terms", nullable = false)
    private int terms = 14;

    /** The percent of an overdue claim's figure added for every full 30 days it is overdue. */
    @Column(name = "late_pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal latePct = new BigDecimal("0.00");

    /** The date claims round by: one before it rounds half up, one on or after it half to even; null for today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** The date from which claims opened are numbered within their period; null (blank) for off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {
    }

    public Sheet(String id) {
        this.id = id;
        this.createdAt = Instant.now();
        this.today = LocalDate.now();
    }

    public String getId() {
        return id;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public BigDecimal getClerkLimit() {
        return clerkLimit;
    }

    public void setClerkLimit(BigDecimal clerkLimit) {
        this.clerkLimit = clerkLimit;
    }

    public BigDecimal getFloor() {
        return floor;
    }

    public void setFloor(BigDecimal floor) {
        this.floor = floor;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    public BigDecimal getLatePct() {
        return latePct;
    }

    public void setLatePct(BigDecimal latePct) {
        this.latePct = latePct;
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    /**
     * How a claim's live figures round, by the date its rounding follows: half up before the policy date (the
     * sheet's today when it is blank), half to even on or after it.
     */
    public RoundingMode roundingOn(LocalDate roundsOn) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return policy != null && roundsOn.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }
}
-- The least a claim's live due can be; it starts at 1.00.
ALTER TABLE sheet ADD COLUMN due_floor DECIMAL(14, 2) DEFAULT 1.00 NOT NULL CHECK (due_floor >= 0);
-- The role a user name has on a sheet: clerk or steward. A name with no row is a clerk.
CREATE TABLE sheet_role (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name VARCHAR(100) NOT NULL,
    role      VARCHAR(20)  NOT NULL CHECK (role IN ('clerk', 'steward'))
);
CREATE UNIQUE INDEX sheet_role_user ON sheet_role (sheet_id, user_name);
-- The most a clerk may settle a claim for; null means no limit.
ALTER TABLE sheet ADD COLUMN clerk_limit DECIMAL(14, 2) CHECK (clerk_limit >= 0);

